11: export const RELATE_VERSION = "0.1.0";
12: export const TAXONOMY_V1: readonly Relation[] = ["SUPPORTS", "CONTRADICTS", "UPDATES", "IMPLEMENTS", "RELATED", "UNKNOWN"];
