14: const NEG_RE = /\b(not|no|never|n't|non|cannot|can't|unable|fails?|failed|failure|violates?|rejects?|denies|denied|prohibits?|forbids?|forbidden|without|except|refutes?)\b/gi;
15: const TEMPORAL_RE = /\b(20\d\d[-./]\d\d?[-./]\d\d?|20\d\d|v\d+(?:\.\d+)+|version\s+\d+|firmware\s+(?:below|above|<|>|<=|>=)?\s*\d[\d.]*)\b/gi;
16: const REQUIRE_RE = /\b(requires?|must|shall|should|mandat\w*|policy|prohibit\w*|forbid\w*|never\s+\w+\s+in\s+place)\b/gi;
17: const MECHANISM_RE = /\b(appends?|implements?|enforces?|performs?|executes?|writes?|immutable|never\s+updates?|redirects?|batches?|queues?)\b/gi;
18: const ENTITY_RE = /\b([A-Z][A-Za-z0-9_]*(?:[._-][A-Za-z0-9_]+)+|[A-Z]{2,}[A-Za-z0-9_]*|\b\d[\d.,_-]*\b)\b/g;
19: const QUALIFIER_RE = /\b(only|except|unless|only\s+if|solely|merely|just|but|however|although|subgroup|allow-list\w*|internal\s+callers?)\b/gi;
