29: function tokens(text: string): Set<string> {
30:   return new Set(text.toLowerCase().match(/[a-z0-9_]+/g) ?? []);
31: }
32: 
33: /** Content overlap: stopword-filtered, so function words cannot create relatedness. */
34: function overlap(a: string, b: string): number {
35:   const content = (text: string): Set<string> => {
36:     const out = new Set<string>();
37:     for (const t of tokens(text)) if (!STOPWORDS.has(t)) out.add(t);
38:     return out;
39:   };
40:   const ta = content(a);
41:   const tb = content(b);
42:   if (ta.size === 0 || tb.size === 0) return 0;
43:   let inter = 0;
44:   for (const t of ta) if (tb.has(t)) inter++;
45:   return inter / Math.min(ta.size, tb.size);
46: }
47: 
48: function spans(text: string, re: RegExp, role: EvidenceSpan["role"], limit = 4): EvidenceSpan[] {
49:   const out: EvidenceSpan[] = [];
50:   re.lastIndex = 0;
51:   let m: RegExpExecArray | null;
52:   while ((m = re.exec(text)) !== null && out.length < limit) {
53:     out.push({ excerpt: m[0], role });
54:     if (m[0].length === 0) re.lastIndex++;
55:   }
56:   re.lastIndex = 0;
57:   return out;
58: }
59: 
60: function entities(text: string): Set<string> {
61:   const out = new Set<string>();
62:   ENTITY_RE.lastIndex = 0;
63:   let m: RegExpExecArray | null;
64:   while ((m = ENTITY_RE.exec(text)) !== null) out.add(m[0].toLowerCase());
65:   ENTITY_RE.lastIndex = 0;
66:   return out;
67: }
68: 
69: /** Shared content referents: identifiers/entities plus non-stopword content tokens.
70:  *  Heuristic entity detection alone misses common-noun referents ("migration",
71:  *  "fare"), so contradiction/support gates use this broader set. Documented weakness:
72:  *  no stemming, no synonymy, no antonymy (improve/deprecate unseen). */
73: function sharedContent(leftText: string, rightText: string): string[] {
74:   const content = (text: string): Set<string> => {
75:     const out = new Set<string>();
76:     for (const t of tokens(text)) {
77:       if (STOPWORDS.has(t)) continue;
78:       if (t.length >= 4 || /\d/.test(t)) out.add(t);
79:     }
80:     return out;
81:   };
82:   const l = content(leftText);
83:   return [...content(rightText)].filter((t) => l.has(t));
84: }
85: 
86: function contentTokens(text: string): string[] {
87:   const out: string[] = [];
88:   for (const t of tokens(text)) {
89:     if (STOPWORDS.has(t)) continue;
90:     if (t.length >= 4 || /\d/.test(t)) out.push(t);
91:   }
92:   return out;
93: }
94: 
95: /** True when a negation cue sits within ±2 tokens of the target token. */
96: function cueNear(text: string, target: string): boolean {
97:   const toks = [...tokens(text)];
98:   for (let i = 0; i < toks.length; i++) {
99:     if (toks[i] !== target) continue;
100:     for (let j = Math.max(0, i - 2); j <= Math.min(toks.length - 1, i + 2); j++) {
101:       if (j === i) continue;
102:       NEG_RE.lastIndex = 0;
103:       if (NEG_RE.test(toks[j])) {
104:         NEG_RE.lastIndex = 0;
105:         return true;
106:       }
107:       NEG_RE.lastIndex = 0;
108:     }
109:   }
110:   return false;
111: }
112: 
113: function polarity(text: string): boolean {
114:   NEG_RE.lastIndex = 0;
115:   const hits = text.match(NEG_RE) ?? [];
116:   NEG_RE.lastIndex = 0;
117:   return hits.length > 0;
118: }
119: 
120: /** Shared content token negated on exactly one side (e.g. "may read" /
121:  *  "may not read", "refundable" / "non-refundable"). Strongest signal:
122:  *  same predicate, opposite polarity. Documented gap: antonymy without
123:  *  shared stems (improve/deprecate) is invisible to this check. */
124: function sharedPredicateNegation(leftText: string, rightText: string, shared: string[]): string | null {
125:   const lct = new Set(contentTokens(leftText));
126:   const rct = new Set(contentTokens(rightText));
127:   for (const t of shared) {
128:     if (!lct.has(t) || !rct.has(t)) continue;
129:     const ln = cueNear(leftText, t);
130:     const rn = cueNear(rightText, t);
131:     if (ln !== rn) return t;
132:   }
133:   return null;
134: }
