136: export interface ClassifyOptions {
137:   model?: string;
138: }
139: 
140: export function classifyPair(leftText: string, rightText: string, left: SourceRef, right: SourceRef, options: ClassifyOptions = {}): RelationObservation {
141:   if (!leftText || leftText.trim().length === 0 || !rightText || rightText.trim().length === 0) {
142:     throw new RelateError("EMPTY_INPUT", "both sides must be non-empty strings");
143:   }
144:   const base = {
145:     observation_id: "",
146:     left,
147:     right,
148:     producer: { plugin: "opencode-relate" as const, version: RELATE_VERSION, ...(options.model ? { model: options.model } : {}) },
149:     notes: ["method:heuristic-v0.1 — cue-based, uncalibrated; UNKNOWN is success, not failure."],
150:   };
151:   const finish = (relation: Relation, direction: Direction, confidence: number, evidence: EvidenceSpan[], unknown_reason?: string): RelationObservation => ({
152:     ...base,
153:     observation_id: stableId(["relate", RELATE_VERSION, left.id, right.id, leftText, rightText, relation, direction]),
154:     relation,
155:     direction,
156:     confidence,
157:     evidence,
158:     status: relation === "UNKNOWN" ? "unknown" : "observed",
159:     ...(unknown_reason ? { unknown_reason } : {}),
160:   });
161: 
162:   const ov = overlap(leftText, rightText);
163:   const le = entities(leftText);
164:   const re = entities(rightText);
165:   const sharedEntities = [...le].filter((e) => re.has(e));
166:   const shared = [...new Set([...sharedEntities, ...sharedContent(leftText, rightText)])];
167:   const entityEvidence: EvidenceSpan[] = shared.slice(0, 4).map((e) => ({ excerpt: e, role: "entity" as const }));
168:   const negatedPredicate = sharedPredicateNegation(leftText, rightText, shared);
169:   const lp = polarity(leftText);
170:   const rp = polarity(rightText);
171: 
172:   // Gate: no shared referents and low overlap → insufficient evidence.
173:   if (shared.length === 0 && ov < 0.15) {
174:     return finish("UNKNOWN", "not_applicable", 0.1, [], "no shared entities and lexical overlap below 0.15");
175:   }
176: 
177:   // 1a. Shared-predicate negation: same predicate, opposite polarity.
178:   // Strongest signal; checked before implements so "never updates" style
179:   // mechanism language is not mistaken for opposition without a shared target.
180:   if (negatedPredicate !== null) {
181:     const evidence = [...entityEvidence, { excerpt: negatedPredicate, role: "negation" as const }];
182:     return finish("CONTRADICTS", "symmetric", 0.6, evidence);
183:   }
184: 
185:   // 1b. Generic polarity mismatch: one side negated, the other not, with
186:   // shared referents — but only after the implements check below has had its
187:   // chance (mechanism language like "never updates" must not read as opposition).
188:   const genericMismatch = shared.length > 0 && lp !== rp;
189:   // 2. Update: shared referents + differing temporal/version markers.
190:   // (Placed before implements: a dated revision claim outranks mechanism reading.)
191:   const lt = [...leftText.matchAll(TEMPORAL_RE)].map((m) => m[0].toLowerCase());
192:   const rt = [...rightText.matchAll(TEMPORAL_RE)].map((m) => m[0].toLowerCase());
193:   const temporalDiff = lt.filter((t) => !rt.includes(t)).length > 0 || rt.filter((t) => !lt.includes(t)).length > 0;
194:   if (shared.length > 0 && (lt.length > 0 || rt.length > 0) && temporalDiff) {
195:     const evidence = [
196:       ...entityEvidence,
197:       ...spans(leftText, TEMPORAL_RE, "temporal", 2),
198:       ...spans(rightText, TEMPORAL_RE, "temporal", 2),
199:     ];
200:     // Direction: side carrying the newer/superseding marker updates the other.
201:     // Heuristic cannot order markers reliably → point from the side with MORE
202:     // temporal markers, else record direction uncertainty in notes.
203:     const direction: Direction = rt.length !== lt.length ? (rt.length > lt.length ? "right_to_left" : "left_to_right") : "symmetric";
204:     return finish("UPDATES", direction, 0.45, evidence);
205:   }
206: 
207:   // 3. Implements: requirement language on one side, mechanism on the other.
208:   const lReq = REQUIRE_RE.test(leftText);
209:   REQUIRE_RE.lastIndex = 0;
210:   const rReq = REQUIRE_RE.test(rightText);
211:   REQUIRE_RE.lastIndex = 0;
212:   const lMech = MECHANISM_RE.test(leftText);
213:   MECHANISM_RE.lastIndex = 0;
214:   const rMech = MECHANISM_RE.test(rightText);
215:   MECHANISM_RE.lastIndex = 0;
216:   if (shared.length > 0 && ((lReq && rMech) || (rReq && lMech))) {
217:     const reqSide = lReq && !rReq ? leftText : rReq && !lReq ? rightText : null;
218:     const mechSide = lMech && !rMech ? leftText : rMech && !lMech ? rightText : null;
219:     const evidence = [
220:       ...entityEvidence,
221:       ...(reqSide ? spans(reqSide, REQUIRE_RE, "requirement", 2) : []),
222:       ...(mechSide ? spans(mechSide, MECHANISM_RE, "mechanism", 2) : []),
223:     ];
224:     const direction: Direction = mechSide === leftText ? "left_to_right" : mechSide === rightText ? "right_to_left" : "symmetric";
225:     return finish("IMPLEMENTS", direction, 0.5, evidence);
226:   }
227: 
228:   // 3b. Generic polarity mismatch (evaluated after implements so mechanism
229:   // language like "never updates" is not mistaken for opposition).
230:   if (genericMismatch) {
231:     const evidence = [...entityEvidence, ...spans(lp ? leftText : rightText, NEG_RE, "negation")];
232:     return finish("CONTRADICTS", "symmetric", 0.5, evidence);
233:   }
234: 
235:   // 4. Supports: shared referents + same polarity + substantive overlap.
236:   if (shared.length > 0 && lp === rp && ov >= 0.3) {
237:     const evidence = [...entityEvidence, ...spans(leftText, QUALIFIER_RE, "qualifier", 2), ...spans(rightText, QUALIFIER_RE, "qualifier", 2)];
238:     const direction: Direction = rightText.length !== leftText.length ? (rightText.length > leftText.length ? "right_to_left" : "left_to_right") : "symmetric";
239:     return finish("SUPPORTS", direction, 0.4, evidence);
240:   }
241: 
242:   // 5. Related: shared topic/referents, nothing stronger established.
243:   if (shared.length > 0 || ov >= 0.15) {
244:     const overlapEvidence: EvidenceSpan[] = [
245:       ...entityEvidence,
246:       ...shared.slice(0, 2).map((e) => ({ excerpt: e, role: "overlap" as const })),
247:     ];
248:     return finish("RELATED", "symmetric", 0.3, overlapEvidence.slice(0, 4));
249:   }
250: 
251:   return finish("UNKNOWN", "not_applicable", 0.1, [], "no relation cue met its threshold");
252: }

