import { readFileSync } from "node:fs";
import { rankCandidates, cosineScore, pseudoRandomScore } from "./src/engine/compatibility.ts";
import { classifyPair } from "./src/engine/classify.ts";

const battery = JSON.parse(readFileSync(new URL("./tests/action-battery.json", import.meta.url), "utf-8"));

function projectionScore(subject: string, candidate: string): number {
  const o = classifyPair(subject, candidate, { id: "s", kind: "t" }, { id: "c", kind: "t" });
  if (o.relation === "UNKNOWN") return 0.1;
  if (o.relation === "RELATED") return 0.3;
  return o.confidence;
}

for (const c of battery.cases) {
  const all = [
    ...(c.positive ? [c.positive] : []),
    ...(c.extra_acceptable ?? []),
    ...c.negatives,
  ];
  const r = rankCandidates(c.subject, all.map((x) => ({ id: x.id, text: x.text })), c.relation, {
    subject_kind: c.subject_kind, candidate_kind: c.candidate_kind,
  });
  const order = r.candidates.map((x) => `${x.candidate_id}:${x.score}`).join(" ");
  const cos = all.map((x) => `${x.id}:${cosineScore(c.subject, x.text)}`).sort((a, b) => parseFloat(b.split(":")[1]!) - parseFloat(a.split(":")[1]!)).join(" ");
  const proj = all.map((x) => `${x.id}:${projectionScore(c.subject, x.text)}`).sort((a, b) => parseFloat(b.split(":")[1]!) - parseFloat(a.split(":")[1]!)).join(" ");
  console.log(`### ${c.id} [${r.status} top=${r.top_candidate} margin=${r.margin}]`);
  console.log(`  compat: ${order}`);
  console.log(`  cosine: ${cos}`);
  console.log(`  proj:   ${proj}`);
}

